#' Utility Functions
#'
#' General utility functions used across the simulation framework

#' Null-coalescing operator
#'
#' Returns the left-hand side if not NULL, otherwise returns the right-hand side
#'
#' @param a First value to check
#' @param b Default value if a is NULL
#' @return Either a or b
#' @noRd
`%||%` <- function(a, b) {
  if (is.null(a)) b else a
}

#' Check and load required packages
#'
#' @param packages Character vector of package names
#' @param required Logical vector indicating which packages are required
#' @return Invisible NULL
#' @noRd
check_packages <- function(packages, required = rep(TRUE, length(packages))) {
  for (i in seq_along(packages)) {
    pkg <- packages[i]
    if (!requireNamespace(pkg, quietly = TRUE)) {
      if (required[i]) {
        stop(paste("Package", pkg, "is required but not installed."))
      } else {
        warning(paste("Optional package", pkg, "is not installed. Some features may be unavailable."))
      }
    }
  }
  invisible(NULL)
}

#' Generate timestamp string
#'
#' @param format Character string specifying format (default: "%Y%m%d_%H%M%S")
#' @return Character string with formatted timestamp
#' @noRd
generate_timestamp <- function(format = "%Y%m%d_%H%M%S") {
  format(Sys.time(), format)
}

#' Derive a reproducible random-number stream seed
#'
#' The seed depends on sample size, simulation number, and a named stream rather
#' than loop position. This makes a cached table row reproducible when sample
#' sizes or target models are added, removed, or reordered.
#'
#' @param seed Base simulation seed or NULL.
#' @param sample_size Current sample size.
#' @param simulation Current simulation index.
#' @param stream Stream label such as "data" or a model name.
#' @return Integer seed or NULL.
#' @noRd
derive_simulation_seed <- function(seed, sample_size, simulation, stream = "data") {
  if (is.null(seed)) return(NULL)
  if (!is.numeric(seed) || length(seed) != 1 || is.na(seed)) {
    stop("seed must be NULL or a single non-missing numeric value")
  }

  stream_values <- utf8ToInt(as.character(stream))
  stream_code <- sum(stream_values * seq_along(stream_values))
  modulus <- .Machine$integer.max - 1
  derived <- (
    abs(as.double(seed)) +
      as.double(sample_size) * 1000003 +
      as.double(simulation) * 1009 +
      as.double(stream_code) * 9176
  ) %% modulus

  as.integer(derived + 1)
}

#' Process sample size specification
#'
#' @param sample_sizes Either a numeric vector or list(min, max, step)
#' @return Numeric vector of sample sizes
#' @noRd
process_sample_sizes <- function(sample_sizes) {
  if (is.list(sample_sizes)) {
    if (!all(c("min", "max", "step") %in% names(sample_sizes))) {
      stop("sample_sizes list must contain 'min', 'max', and 'step' elements")
    }
    bounds <- unlist(sample_sizes[c("min", "max", "step")], use.names = FALSE)
    if (!is.numeric(bounds) || length(bounds) != 3 || anyNA(bounds) ||
        any(!is.finite(bounds)) || sample_sizes$step <= 0 ||
        sample_sizes$max < sample_sizes$min) {
      stop("sample_sizes bounds must be finite scalars with min <= max and step > 0")
    }
    sizes <- seq(sample_sizes$min, sample_sizes$max, by = sample_sizes$step)
  } else if (is.numeric(sample_sizes)) {
    sizes <- sample_sizes
  } else {
    stop("sample_sizes must be either a numeric vector or list(min, max, step)")
  }

  if (length(sizes) == 0 || anyNA(sizes) || any(!is.finite(sizes)) ||
      any(sizes <= 1) || any(sizes != floor(sizes))) {
    stop("sample_sizes must contain finite whole numbers greater than 1")
  }

  sort(unique(sizes))
}

#' Supported performance metrics
#' @noRd
supported_metrics <- function() {
  c("mse", "rmse", "mae", "r_squared", "auc", "c_stat", "accuracy",
    "sensitivity", "specificity", "precision", "recall", "f1", "brier")
}

#' Validate simulation arguments before fitting
#' @noRd
validate_simulation_inputs <- function(data_generation, predictor_config,
                                       target_models, n_simulations, metrics,
                                       efficiency_threshold, infinite_n,
                                       cv_folds, cv_repeats, seed, parallel,
                                       verbose, validation_strategy) {
  whole_scalar <- function(x, minimum = 1) {
    is.numeric(x) && length(x) == 1 && !is.na(x) && is.finite(x) &&
      x >= minimum && x == floor(x)
  }
  if (!whole_scalar(n_simulations)) stop("n_simulations must be a positive integer")
  if (!whole_scalar(cv_repeats)) stop("cv_repeats must be a positive integer")
  if (!is.null(cv_folds) && (!whole_scalar(cv_folds, 0) || cv_folds == 1)) {
    stop("cv_folds must be NULL, 0, or an integer of at least 2")
  }
  if (validation_strategy == "ordered" && identical(as.numeric(cv_folds), 0)) {
    stop("Ordered validation requires out-of-sample evaluation; cv_folds cannot be 0")
  }
  if (!is.null(infinite_n) && !whole_scalar(infinite_n, 2)) {
    stop("infinite_n must be NULL or a finite integer greater than 1")
  }
  if (!is.null(seed) && (!whole_scalar(seed, 0) || seed > .Machine$integer.max)) {
    stop("seed must be NULL or a nonnegative integer no larger than .Machine$integer.max")
  }
  if (!is.logical(parallel) || length(parallel) != 1 || is.na(parallel)) {
    stop("parallel must be TRUE or FALSE")
  }
  if (parallel) stop("parallel = TRUE is not implemented; use parallel = FALSE")
  if (!is.logical(verbose) || length(verbose) != 1 || is.na(verbose)) {
    stop("verbose must be TRUE or FALSE")
  }
  validate_threshold(efficiency_threshold)
  if (!is.character(target_models) || !length(target_models) || anyNA(target_models)) {
    stop("target_models must be a nonempty character vector without missing values")
  }
  if (!is.character(metrics) || !length(metrics) || anyNA(metrics) ||
      anyDuplicated(metrics) || any(!metrics %in% supported_metrics())) {
    stop("metrics must be unique supported names: ", paste(supported_metrics(), collapse = ", "),
         "; adj_r_squared and efficiency are not standalone prediction metrics")
  }
  if (!is.list(data_generation) || !is.character(data_generation$method) ||
      length(data_generation$method) != 1 || is.na(data_generation$method) ||
      !data_generation$method %in% c("joint_mvn", "synthetic", "parametric", "empirical")) {
    stop("data_generation$method must be joint_mvn, synthetic, parametric, or empirical")
  }
  if (!is.list(predictor_config) || !is.character(predictor_config$names) ||
      !length(predictor_config$names) || anyNA(predictor_config$names) ||
      anyDuplicated(predictor_config$names) || any(!nzchar(predictor_config$names)) ||
      any(predictor_config$names %in% c("y", ".group"))) {
    stop("predictor_config$names must be unique, nonempty names other than y or .group")
  }
  if (!is.null(predictor_config$types) &&
      (length(predictor_config$types) != length(predictor_config$names) ||
       anyNA(predictor_config$types) ||
       any(!predictor_config$types %in% c("continuous", "binary", "categorical")))) {
    stop("predictor types must match names and be continuous, binary, or categorical")
  }
  invisible(TRUE)
}

#' Validate a relative performance threshold
#' @noRd
validate_threshold <- function(threshold) {
  if (!is.numeric(threshold) || length(threshold) != 1 || is.na(threshold) ||
      !is.finite(threshold) || threshold <= 0 || threshold > 1) {
    stop("efficiency_threshold must be a finite number in (0, 1]")
  }
  invisible(TRUE)
}

#' Validate configuration parameters
#'
#' @param config List with configuration parameters
#' @return Logical TRUE if valid, otherwise throws error
#' @noRd
validate_configuration <- function(config) {
  # Check predictor_config
  if (!is.null(config$predictor_config)) {
    pc <- config$predictor_config
    if (!all(c("names", "types") %in% names(pc))) {
      stop("predictor_config must contain 'names' and 'types' elements")
    }
    if (length(pc$names) != length(pc$types)) {
      stop("Length of predictor names and types must match")
    }
  }

  # Check data_generation
  if (!is.null(config$data_generation)) {
    dg <- config$data_generation
    if (!"method" %in% names(dg)) {
      stop("data_generation must contain 'method' element")
    }
    valid_methods <- c("joint_mvn", "synthetic", "parametric", "empirical")
    if (!dg$method %in% valid_methods) {
      stop(paste("data_generation method must be one of:", paste(valid_methods, collapse = ", ")))
    }
  }

  # Check metrics
  if (!is.null(config$metrics)) {
    valid_metrics <- supported_metrics()
    invalid_metrics <- setdiff(config$metrics, valid_metrics)
    if (length(invalid_metrics) > 0) {
      warning(paste("Unknown metrics:", paste(invalid_metrics, collapse = ", ")))
    }
  }

  return(TRUE)
}

#' Create progress bar
#'
#' @param total Total number of iterations
#' @param label Label for progress bar
#' @return Progress bar object (if available) or NULL
#' @noRd
create_progress_bar <- function(total, label = "Progress") {
  if (requireNamespace("progress", quietly = TRUE)) {
    progress::progress_bar$new(
      format = paste0(label, " [:bar] :percent eta: :eta"),
      total = total,
      clear = FALSE,
      width = 60
    )
  } else {
    NULL
  }
}
